    setAutomaticSubstitutions: function(checked, employee_substituted_id, employee_substitute_id){
        var preFilter = [];
        var replacements = [];
        var mask = new Ext.LoadMask(Ext.getBody(), {msg: 'Consultando substitutos...'});
        if(checked == true && employee_substituted_id != undefined && employee_substitute_id == undefined){
            this._automaticSubstitutions = checked;
            this.setDone(false);
            mask.show();
            this.getEmployeeField().setReadOnly(true);
            callSetPreFilter = false;
            Ext.Ajax.request({
                scope: this,
                url: toolkit.util.Normalize.controller_action('RHEmployeeSubstitutesRestful', 'get_substitutes'),
                params: {
                    employee_substituted: employee_substituted_id,
                },
                callback: function() {},
                success: function(xhr) {
                    mask.hide();
                    this.getEmployeeField().setReadOnly(false);
                    var rst = Ext.decode(xhr.responseText);
                    if(rst.success) {
                        for(x in rst.result){
                            if(rst.result.hasOwnProperty(x))
                                replacements.push(rst.result[x]);
                        }
                        if(!this.values.servidor){
                            callSetPreFilter = false;
                            this.setPreFilterEmployeeField(replacements);
                        }
                    }else{
                        Ext.Msg.show({
                            title: 'Informando',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: rst.message
                        });
                    }
                    this.setDone(true);
                },
                failure: function(xhr) {
                    mask.hide();
                    this.setDone(true);
                    this.getEmployeeField().setReadOnly(false);
                    Ext.Msg.show({
                        title: 'Informando',
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: 'Não foi possível verificar a tabela de substituição automática.'
                    });
                }
            });
        }else{
            this.setDone(true)
        }
        if(this._automaticSubstitutions != checked && employee_substitute_id == undefined){
            callSetPreFilter = true;
            this._automaticSubstitutions = checked;
        }
        if(this.values && employee_substitute_id){
            callSetPreFilter = true;
            preFilter = [{
                property: 'pk',
                value: employee_substitute_id,
                stage: 0
            }];
        }
        if(callSetPreFilter == true){
            var own = this;
            own.setPreFilterEmployeeField(replacements, preFilter);
            setTimeout(function() {
                own.getEmployeeField().setValue(employee_substitute_id);
            }, 1000);
        }
    },

    setPreFilterEmployeeField: function(replacements, preFilter){
        preFilter = core.nullValue(preFilter, []);
        if(replacements.length != undefined && replacements.length != 0)
            preFilter.push({
                property: 'matricula__in',
                value: replacements,
                stage: 0
            });
        this.getEmployeeField().setPreFilter(preFilter);
        this.getEmployeeField().getComboField().store.baseParams['employee_substituted'] = this.values.servidor_substituido;
        this.getEmployeeField().getComboField().store.load();
    },

    getAutomaticReplacement: function(cfg_window){
        if(!this._automaticReplacement){
            this._automaticReplacement = Ext._create('Ext.form.Checkbox', {
                checked: true,
                fieldLabel: 'Listar Substituto automático?',
                xtype: 'checkbox',
                name: 'automatic_substitute',
                allowBlank: true,
                listeners: {
                    scope: this,
                    check: function(checkbox, checked){
                        this._observe();
                    }
                }
            });
        }
        return this._automaticReplacement;
    },

